/**
 * Result of initiating a payout-account link. The provider driver decides how
 * the expert reaches the hosted onboarding flow.
 */
export interface LinkInitiateResult {
  /** 'redirect' — expert browser opens a hosted onboarding URL. */
  readonly type: 'redirect';
  /** Hosted onboarding URL the expert browser should open. */
  readonly url: string;
  /** One-time state value bound to this link attempt (CSRF + idempotency). */
  readonly state: string;
}

/**
 * Result of initiating a payout-account link via form (no redirect).
 * Returned when the driver uses a direct API flow (e.g. RazorpayX):
 * the frontend renders a bank details form instead of redirecting.
 */
export interface LinkInitiateFormResult {
  /** Always 'form' for direct API flows. */
  readonly type: 'form';
  /** Field names the frontend should collect from the expert. */
  readonly fields: string[];
  /** Empty string — no redirect URL for form-type flows. */
  readonly url: string;
}

export type LinkInitiateResultOrForm = LinkInitiateResult | LinkInitiateFormResult;

/**
 * Normalized provider account record returned after a successful link
 * completion.
 */
export interface LinkedAccount {
  /** Provider account id (e.g. Razorpay acc_xxx, Stripe acct_123). */
  readonly externalAccountId: string;
  /** Provider access token (encrypted at rest by the caller). */
  readonly accessToken: string;
  /** Provider refresh token (encrypted at rest by the caller). */
  readonly refreshToken?: string;
  /** When the access token expires (ISO string), if known. */
  readonly tokenExpiresAt?: string;
  /** Driver-specific extra payload to store verbatim. */
  readonly raw: Record<string, unknown>;
}

/**
 * Standardized payout-account status fetched from the provider.
 */
export interface AccountStatus {
  /** Whether the provider account is active and can receive payouts. */
  readonly active: boolean;
  /** Provider-facing status string (e.g. 'active', 'pending', 'rejected'). */
  readonly status: string;
  /** Human-readable failure reason, if any. */
  readonly failureReason?: string;
}

/**
 * Parsed webhook event from a provider. Returned by parseWebhook after
 * signature verification; null means the event should be ignored (not for this
 * app, unverified, or already processed).
 */
export interface PaymentProviderOnboarderWebhookEvent {
  /** Provider account id the event refers to. */
  readonly externalAccountId: string;
  /** Normalized event type (e.g. 'account.activated', 'kyc.rejected'). */
  readonly eventType: string;
  /** Provider-specific raw event payload. */
  readonly raw: Record<string, unknown>;
}

/**
 * Context passed to a driver when initiating a link for a specific expert.
 */
export interface OnboarderExpertContext {
  /** Expert's internal id. */
  readonly expertId: number;
  /** Callback URL the provider redirects to after the expert completes
   * onboarding. */
  readonly redirectUri: string;
  /** One-time state value generated by the use-case. */
  readonly state: string;
}

/**
 * Generic payout-account onboarding driver interface.
 *
 * Each supported provider (Razorpay Partner, Stripe Express, Cashfree, …)
 * gets its own driver implementing this interface. Use-cases depend only on
 * this interface (via the PAYMENT_PROVIDER_ONBOARDER DI token), never on a
 * concrete driver, so the unified `payment/` class is untouched and adding a
 * platform is a new driver directory, not an edit to existing code.
 *
 * See {@link PAYMENT_PROVIDER_ONBOARDER} for the DI token.
 */
export interface PaymentProviderOnboarder {
  /** Stable provider key, matches `payment.providers.code` and the
   * `payment_provider` column in `payments.partner_payout_accounts`. */
  readonly provider: string;

  /**
   * Build the provider-hosted onboarding URL for the expert.
   * Called when the expert initiates a bank-account link.
   *
   * Returns either `{ type: 'redirect', url, state }` for hosted flows
   * (Razorpay Partner) or `{ type: 'form', fields }` for direct API flows
   * (RazorpayX).
   */
  initiate(ctx: OnboarderExpertContext): Promise<LinkInitiateResultOrForm>;

  /**
   * Complete the link. For OAuth flows: exchange the authorization code for
   * account tokens. For direct API flows: create platform contact + fund
   * account and initiate penny-drop. Takes bank details instead of code/state.
   */
  complete(input: {
    code?: string;
    state?: string;
    accountHolderName?: string;
    accountNumber?: string;
    ifsc?: string;
  }): Promise<LinkedAccount>;

  /**
   * Fetch the current status of a linked provider account. Used for
   * refresh-status and webhook-driven reconciliation.
   */
  fetchAccountStatus(ctx: {
    externalAccountId: string;
    accessToken: string;
  }): Promise<AccountStatus>;

  /**
   * Optionally deactivate/revoke a provider account when the expert unlinks.
   * Drivers that don't support deactivation may omit this.
   */
  deactivate?(externalAccountId: string): Promise<void>;

  /**
   * Optionally validate a penny-drop amount (direct API flows only).
   * The expert confirms the ₹1 amount received in their bank account.
   */
  validatePennyDrop?(
    validationId: string,
    amount: number,
  ): Promise<{ validated: boolean }>;

  /**
   * Verify a provider webhook signature and parse it into a normalized event.
   * Returns null for events that should be ignored.
   * Throws on signature mismatch.
   */
  parseWebhook(
    headers: Record<string, string | string[] | undefined>,
    rawBody: Buffer,
  ): Promise<PaymentProviderOnboarderWebhookEvent | null>;
}

/** DI token for resolving the active payment-provider onboarding driver. */
export const PAYMENT_PROVIDER_ONBOARDER = 'IPaymentProviderOnboarder';
